#!/usr/bin/env python3
"""Re-vendor the PJRT C API header and regenerate the stub table.

    ./revendor.py --from <openxla/xla checkout, or the header itself>

The header is copied verbatim. Point it at whatever tree carries the version
you intend to build against -- an openxla/xla checkout, or the copy the client
was itself built against, which is stronger: the plugin and its caller have to
agree on the API exactly, because the caller fills in each `_Args` struct's
`struct_size` from its own header and the plugin reads it. A skew is not a
compile error but a silently truncated struct at run time.

It also regenerates src/iree_pjrt/common/stubs.inc, the list BindUndefineds()
walks to point every PJRT_Api field at an UNIMPLEMENTED stub before the real
implementations overwrite the supported ones. That list has to name *every*
field in the header: one it misses stays NULL, and a caller that invokes it
segfaults instead of getting an error back. Deriving it from the header we just
vendored is what keeps the two from drifting -- going 0.68 to 0.114 added 26
fields, every one of which would otherwise have been a NULL function pointer.
"""

import argparse
import pathlib
import re
import sys

HEADER_REL = "xla/pjrt/c/pjrt_c_api.h"
STUBS_DST = "../../src/iree_pjrt/common/stubs.inc"


def find_header(source):
    """Accept the header itself, a tree rooted where xla/ lives, or a checkout."""
    if source.is_file():
        return source
    direct = source / HEADER_REL
    if direct.is_file():
        return direct
    matches = sorted(source.glob("**/" + HEADER_REL))
    if len(matches) == 1:
        return matches[0]
    if len(matches) > 1:
        sys.exit(
            f"ambiguous: several copies of the header under {source}; "
            "pass one directly\n  " + "\n  ".join(str(m) for m in matches)
        )
    return None


def api_fields(text):
    """Every PJRT_Api function-pointer field, in declaration order.

    Read from the struct body alone rather than the whole header: the macro
    name appears in the surrounding commentary too, and a stub for something
    that is not a field would not compile.
    """
    start = text.index("typedef struct PJRT_Api {")
    body = text[start : text.index("} PJRT_Api;", start)]
    # \s* spans newlines: the longer field names are wrapped in the header.
    return re.findall(r"_PJRT_API_STRUCT_FIELD\(\s*(\w+)\s*\)", body)


def api_version(text):
    major = re.search(r"^#define PJRT_API_MAJOR (\d+)", text, re.M)
    minor = re.search(r"^#define PJRT_API_MINOR (\d+)", text, re.M)
    if not major or not minor:
        sys.exit("could not read PJRT_API_MAJOR/MINOR from the header")
    return f"{major.group(1)}.{minor.group(1)}"


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument(
        "--from",
        dest="source",
        type=pathlib.Path,
        required=True,
        help="pjrt_c_api.h, or a tree containing " + HEADER_REL,
    )
    args = ap.parse_args()

    here = pathlib.Path(__file__).resolve().parent
    src = find_header(args.source)
    if src is None:
        sys.exit(f"no {HEADER_REL} found at or under {args.source}")

    text = src.read_text()
    version = api_version(text)

    # Some downstreams rename the PJRT_Api function-pointer fields (appending an
    # underscore) because in C++ a member named identically to its own type is
    # ambiguous in some contexts. That is a name change only -- offsets and
    # therefore the ABI are untouched -- but this tree assigns the upstream
    # names, so such a header would not build here.
    if "fn_type##_" in text:
        sys.exit(
            f"{src} has renamed PJRT_Api fields (fn_type##_).\n"
            "This tree assigns the upstream names; vendor from an unmodified "
            "header, or normalize it before pointing this script at it."
        )

    (here / HEADER_REL).write_text(text)

    fields = api_fields(text)
    if not fields:
        sys.exit("found no PJRT_Api fields in the vendored header")
    (here / STUBS_DST).write_text(
        "// Generated by third_party/pjrt_c_api/revendor.py -- do not edit.\n"
        "//\n"
        "// Every field of PJRT_Api, for BindUndefineds() in api_impl.cc. A\n"
        "// field missing here keeps a NULL function pointer and segfaults the\n"
        "// caller instead of returning UNIMPLEMENTED, so this is generated\n"
        f"// from the header rather than maintained by hand. {len(fields)} fields.\n"
        "\n" + "".join(f"  _STUB({name});\n" for name in fields)
    )

    (here / "README.md").write_text(
        "# pjrt_c_api\n"
        "\n"
        "This directory contains a fork of the C headers and .proto files\n"
        "needed to build a PJRT plugin.\n"
        "\n"
        "`pjrt_c_api.h` is copied verbatim. Re-vendor with\n"
        "`./revendor.py --from <checkout>`, which also regenerates the stub\n"
        "table in `src/iree_pjrt/common/stubs.inc`; see the script's docstring\n"
        "for why that has to be generated rather than maintained by hand.\n"
        "\n"
        "Last synced from:\n"
        "\n"
        "* https://github.com/openxla/xla.git\n"
        f"* PJRT API version: {version}\n"
    )

    print(f"vendored {HEADER_REL} at PJRT API version {version}")
    print(f"  source: {src}")
    print(f"generated {STUBS_DST} with {len(fields)} stubs")
    # Not a suggestion. CMake does not track this header as a dependency of the
    # plugin's translation units, so an incremental build after re-vendoring
    # recompiles nothing and links a binary that mixes struct layouts from two
    # API versions -- a wrong offset at run time rather than a compile error.
    print()
    print("NOTE: delete the build directory and rebuild from scratch.")
    print("      An incremental build will silently mix API versions.")


if __name__ == "__main__":
    main()
